/*
 Problem: 75. Sort Colors
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 11.7 MB (11.48%)
 Tags: Array, Two Pointers, Sorting
*/
class Solution {
public:
    void sortColors(vector<int>& nums) {
        int low = 0, mid = 0, high = nums.size() - 1;

        while (mid <= high) {
            if (nums[mid] == 0) {
                swap(nums[low], nums[mid]);
                low++;
                mid++;
            } else if (nums[mid] == 1) {
                mid++;
            } else { // nums[mid] == 2
                swap(nums[mid], nums[high]);
                high--;
            }
        }
    }
};
